const pub = $('获取正式壁纸池').first().json || {};
const cfg = $('获取图床页面配置').first().json || {};
const files = Array.isArray(pub.files) ? pub.files : [];
const urls = files
  .map(f => '/file/' + String(f.name || '').split('/').map(encodeURIComponent).join('/'))
  .filter(u => u.length > 6)
  .sort();

const configList = Array.isArray(cfg.config) ? cfg.config : [];
const getVal = (id) => {
  const it = configList.find(x => x.id === id);
  return it ? String(it.value || '') : '';
};

const targetJson = JSON.stringify(urls);
const needSync = urls.length > 0 && (
  getVal('uploadBkImg') !== targetJson ||
  getVal('loginBkImg') !== targetJson ||
  getVal('adminBkImg') !== targetJson ||
  getVal('adminLoginBkImg') !== targetJson
);

let updatedPageConfig = null;
if (needSync) {
  const cloned = JSON.parse(JSON.stringify(cfg));
  const overrides = {
    wallpaperEnabled: true,
    bkInterval: '45000',
    bkOpacity: '0.95',
    loginBkImg: targetJson,
    uploadBkImg: targetJson,
    adminLoginBkImg: targetJson,
    adminBkImg: targetJson,
  };
  for (const item of cloned.config) {
    if (Object.prototype.hasOwnProperty.call(overrides, item.id)) {
      item.value = overrides[item.id];
    }
  }
  updatedPageConfig = cloned;
}

return [{ json: { needSync, approvedCount: urls.length, updatedPageConfig } }];

const inboxResp = $input.first().json || {};
const inboxFiles = Array.isArray(inboxResp.files) ? inboxResp.files : [];
const inboxCount = inboxFiles.length;

let state = { seenKeys: [], seenMd5: [], seenDims: [], pages: {}, rotWave: 0, lastRun: null };
try {
  const raw = $('解码去重账本').first().json.stateJson || '';
  if (raw.trim()) state = { ...state, ...JSON.parse(raw) };
} catch (_) {}
state.pages = state.pages || {};

const MAX_INBOX = 200;
const DAILY_QUOTA = 24; // 8 rotated broad/themed channels * up to 3 curated masterpieces/day
const quota = inboxCount >= MAX_INBOX ? 0 : Math.min(DAILY_QUOTA, MAX_INBOX - inboxCount);

const WAVES = [
  ['toplist_month', 'orig_girl', 'mygo', 'frieren', 'violet', 'miku', 'oshi', 'spyxfamily'],
  ['toplist_year', 'style_dreamy', 'mujica', 'shinkai', 'arknights', 'fate', 'evangelion', 'genshin'],
  ['toplist_all', 'style_cool', 'bocchi', 'bluearchive', 'starrail', 'wuthering', 'kimetsu', 'yurucamp'],
  ['toplist_hot', 'style_school', 'bangdream', 'gbc', 'rezero', 'madoka', 'nier', 'zzz'],
  ['orig_art', 'style_fantasy', 'lycoris', 'kon', 'euphonium', 'monogatari', 'azurlane', 'touhou'],
];

const rawWave = Number(state.rotWave);
const waveIdx = Number.isFinite(rawWave) && rawWave >= 0 ? (rawWave % WAVES.length) : 0;
const activeSeries = WAVES[waveIdx];

if (quota <= 0) {
  return [{ json: { skipSearch: true, inboxFull: true, inboxCount, quota: 0, maxInbox: MAX_INBOX, waveIdx, totalWaves: WAVES.length, activeSeries } }];
}

const getPage = (series, source) => {
  const key = `${series}:${source}`;
  const v = Number(state.pages[key]);
  return Number.isFinite(v) && v >= 1 ? v : 1;
};

const queries = [];
const metaBase = { skipSearch: false, quota, inboxCount, maxInbox: MAX_INBOX, waveIdx, totalWaves: WAVES.length, activeSeries };

const addWH = (series, q, sorting = 'favorites', extra = '') => {
  const p = getPage(series, 'wallhaven');
  const qPart = q ? `q=${encodeURIComponent(q)}&` : '';
  queries.push({
    json: {
      ...metaBase, series, source: 'wallhaven',
      url: `https://wallhaven.cc/api/v1/search?${qPart}categories=010&purity=100&sorting=${sorting}${extra}&page=${p}`,
    }
  });
};
const addKC = (series, tag) => {
  const p = getPage(series, 'konachan');
  queries.push({
    json: {
      ...metaBase, series, source: 'konachan',
      url: `https://konachan.net/post.json?tags=${encodeURIComponent(tag + ' rating:s')}&limit=40&page=${p}`,
