} catch (_) {}

const seenKeys = new Set(state.seenKeys || []);
const seenMd5 = new Set(state.seenMd5 || []);
const seenDims = new Set(state.seenDims || []);

const STD_DIMS = new Set(['1920x1080','1920x1200','2560x1440','2560x1600','2560x1080','3440x1440','3840x2160','3840x2400','5120x2880']);
const dimKey = (w, h) => {
  const d = `${w}x${h}`;
  return STD_DIMS.has(d) ? '' : d;
};

try {
  const inboxFiles = $('查询待审箱列表').first().json.files || [];
  for (const f of inboxFiles) {
    const fn = String(f.name || '').split('/').pop() || '';
    const m = fn.match(/(wallhaven|konachan|yandere)_([a-zA-Z0-9]+)_(\d+x\d+)\./);
    if (m) {
      seenKeys.add(`${m[1]}:${m[2]}`);
      if (!STD_DIMS.has(m[3])) seenDims.add(m[3]);
    }
  }
} catch (_) {}

const queries = $('需要抓新图吗').all();
const responses = $input.all();
const q0 = queries[0]?.json || {};
const quota = Number(q0.quota || 20);
const activeSeries = Array.isArray(q0.activeSeries) && q0.activeSeries.length
  ? q0.activeSeries
  : Array.from(new Set(queries.map(x => x.json?.series).filter(Boolean)));

const BAD_TAGS = /\b(sketch|lineart|monochrome|greyscale|grayscale|comic|4koma|2koma|manga|speech_bubble|character_sheet|reference_sheet|meme|screenshot|screencap|lowres|ai_generated|ai-generated|nsfw|nude|nipples|pussy|penis|sex|hentai|explicit|questionable|pixel_art|chibi|multiple_views|split_screen|collage|unfinished|wip|watermark|cosplay|photo|real_life|simple_background|white_background|transparent_background|upside-down|upside_down|magazine_scan|calendar|cd_cover|bd_cover|dvd_cover|swimsuit|bikini|lingerie|underwear|panties|cleavage|no_humans|nobody|scenery|landscape|still_life|background_only|architecture|nature)\b/i;

const HIGH_VOL_SERIES = new Set(['toplist_month', 'toplist_year', 'toplist_all', 'toplist_hot', 'orig_girl', 'orig_art', 'style_dreamy', 'style_cool', 'style_school', 'style_fantasy', 'oshi', 'evangelion', 'nier', 'wuthering', 'miku', 'genshin', 'arknights', 'bluearchive', 'touhou', 'azurlane', 'fate']);
const SOURCE_ORDER = ['wallhaven', 'konachan', 'yandere'];

const buckets = {};
for (const se of activeSeries) {
  buckets[se] = { wallhaven: [], konachan: [], yandere: [] };
}

const batchKeys = new Set();
const batchMd5 = new Set();
const batchDims = new Set();

function acceptCandidate(c) {
  if (!c.downloadUrl || !c.thumbUrl || !c.key) return;
  if (seenKeys.has(c.key) || batchKeys.has(c.key)) return;
  if (c.md5 && (seenMd5.has(c.md5) || batchMd5.has(c.md5))) return;
  const dk = dimKey(c.origW || c.w, c.origH || c.h);
  if (dk && (seenDims.has(dk) || batchDims.has(dk))) return;
  const longSide = Math.max(c.w, c.h);
  const shortSide = Math.min(c.w, c.h);
  if (longSide < 1400 || shortSide < 900) return;
  const ratio = c.w / c.h;
  if (ratio < 0.45 || ratio > 2.45) return;
  if (c.tags && BAD_TAGS.test(c.tags)) return;
  if (c.fileSize && c.fileSize > 15 * 1024 * 1024) return;
  c.dimKey = dk;
  batchKeys.add(c.key);
  if (c.md5) batchMd5.add(c.md5);
  if (dk) batchDims.add(dk);
  buckets[c.series][c.source].push(c);
}

for (let i = 0; i < Math.min(queries.length, responses.length); i++) {
  const q = queries[i].json || {};
  const series = q.series;
  const src = q.source;
  const resObj = responses[i].json || {};
  if (resObj.statusCode && resObj.statusCode >= 400) continue;
  let body = resObj.body !== undefined ? resObj.body : resObj;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (_) { continue; }
  }
  if (!body || !buckets[series] || !buckets[series][src]) continue;

  const isHighVol = HIGH_VOL_SERIES.has(series);

  if (src === 'wallhaven') {
    const arr = Array.isArray(body.data) ? body.data : [];
    const minFav = isHighVol ? 35 : 10;
    for (const p of arr) {
      if (p.purity !== 'sfw') continue;
      if (Number(p.favorites || 0) < minFav) continue;
      acceptCandidate({
        series, source: 'wallhaven',
        id: String(p.id || ''),
        key: `wallhaven:${p.id}`,
        md5: '',
        w: Number(p.dimension_x || 0),
        h: Number(p.dimension_y || 0),
        origW: Number(p.dimension_x || 0),
        origH: Number(p.dimension_y || 0),
        communityScore: Number(p.favorites || 0),
        fileSize: Number(p.file_size || 0),
        tags: '',
        thumbUrl: String(p.thumbs?.small || p.thumbs?.large || ''),
        downloadUrl: String(p.path || ''),
      });
    }
  } else if (src === 'konachan' || src === 'yandere') {
    const arr = Array.isArray(body) ? body : [];
    const minScore = isHighVol
      ? (src === 'yandere' ? 20 : 15)
      : (src === 'yandere' ? 8 : 8);
    for (const p of arr) {
      if (p.rating !== 's') continue;
      if (Number(p.score || 0) < minScore) continue;
      const origW = Number(p.width || 0);
      const origH = Number(p.height || 0);
      const origSize = Number(p.file_size || 0);
      const sampleW = Number(p.sample_width || 0);
      const sampleH = Number(p.sample_height || 0);
      const useSample = origSize > 5 * 1024 * 1024 && p.sample_url && Math.max(sampleW, sampleH) >= 1400 && Math.min(sampleW, sampleH) >= 900;
      acceptCandidate({
        series, source: src,
        id: String(p.id || ''),
        key: `${src}:${p.id}`,
        md5: String(p.md5 || '').toLowerCase(),
        w: useSample ? sampleW : origW,
        h: useSample ? sampleH : origH,
        origW, origH,
        communityScore: Number(p.score || 0),
        fileSize: useSample ? Number(p.sample_file_size || 0) : origSize,
        tags: String(p.tags || ''),
        thumbUrl: String(p.preview_url || ''),
        downloadUrl: String(useSample ? p.sample_url : (p.file_url || '')),
      });
    }
  }
}

const shortlist = [];
const bucketSizes = {};
for (const se of activeSeries) {
  for (const so of SOURCE_ORDER) {
    buckets[se][so].sort((a, b) => (b.communityScore - a.communityScore) || ((b.w * b.h) - (a.w * a.h)));
    bucketSizes[`${se}:${so}`] = buckets[se][so].length;
  }
  const picked = [];
  const idx = { wallhaven: 0, konachan: 0, yandere: 0 };
  while (picked.length < 6) {
    let moved = false;
    for (const so of SOURCE_ORDER) {
      if (picked.length >= 6) break;
      if (idx[so] < buckets[se][so].length) {
        picked.push(buckets[se][so][idx[so]++]);
        moved = true;
      }
    }
    if (!moved) break;
  }
  for (const item of picked) shortlist.push(item);
}

if (shortlist.length === 0) {
  return [{ json: { noCandidates: true, bucketSizes, quota, activeSeries } }];
}

return shortlist.map(item => ({
  json: { ...item, noCandidates: false, bucketSizes, quota, activeSeries }
}));

const items = $input.all();
const groups = {};

for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const bin = it.binary && it.binary.thumb;
  if (!bin) continue;
  let buf;
  try {
    buf = await this.helpers.getBinaryDataBuffer(i, 'thumb');
  } catch (_) {
    continue;
  }
  if (!buf || buf.length < 1500) continue;
  const mime = String(bin.mimeType || 'image/jpeg').startsWith('image/') ? bin.mimeType : 'image/jpeg';
  const se = it.json.series || 'original';
  if (!groups[se]) groups[se] = [];
  groups[se].push({
    ...it.json,
    b64: buf.toString('base64'),
    thumbMime: mime,
  });
}

