  }];

  const metaList = [];
  list.forEach((c, idx) => {
    content.push({ type: 'text', text: `图 ${idx}（${c.source}，${c.w}x${c.h}，社区热度 ${c.communityScore}）` });
    content.push({ type: 'image_url', image_url: { url: `data:${c.thumbMime};base64,${c.b64}` } });
    metaList.push({
