const batches = $('按系列组装AI视觉评审包').all().map(x => x.json).filter(x => !x.noBatches);
const aiResponses = $input.all();

const perSeriesWinners = [];
const rejectedKeys = [];
const rejectedMd5 = [];
const rejectedDims = [];
let quota = 24;
let bucketSizes = {};

for (let i = 0; i < Math.min(batches.length, aiResponses.length); i++) {
  const b = batches[i];
  if (b.quota) quota = Number(b.quota);
  if (b.bucketSizes) bucketSizes = b.bucketSizes;
  const cands = b.candidates || [];

  const resp = aiResponses[i]?.json || {};
  const rawText = String(resp.choices?.[0]?.message?.content || '').trim();
  let judgments = [];
  try {
    const m = rawText.match(/\[[\s\S]*\]/);
    if (m) judgments = JSON.parse(m[0]);
  } catch (_) {
    judgments = [];
  }

  const byIdx = new Map();
  for (const j of judgments) {
    if (j && typeof j.idx === 'number') byIdx.set(j.idx, j);
  }

  const seriesKept = [];
  for (const c of cands) {
    const j = byIdx.get(c.idx);
    const score = j ? Number(j.score || 0) : 0;
    const keep = Boolean(j && j.keep === true && score >= 8);
    if (keep) {
      seriesKept.push({
        ...c,
        aiScore: Math.min(10, Math.round(score)),
        aiReason: String(j.reason || '').slice(0, 40),
      });
    } else if (j) {
      if (c.key) rejectedKeys.push(c.key);
      if (c.md5) rejectedMd5.push(c.md5);
      if (c.dimKey) rejectedDims.push(c.dimKey);
    }
  }

  seriesKept.sort((a, b) => (b.aiScore - a.aiScore) || (b.communityScore - a.communityScore));
  const top = seriesKept.slice(0, 3).map(w => {
    const extMatch = w.downloadUrl.match(/\.(jpg|jpeg|png|webp)(?:\?|$)/i);
    const ext = (extMatch ? extMatch[1].toLowerCase() : 'jpg').replace('jpeg', 'jpg');
    return {
      ...w,
      cleanFilename: `${w.series}_s${w.aiScore}_${w.source}_${w.id}_${w.w}x${w.h}.${ext}`,
    };
  });
  if (top.length) perSeriesWinners.push(top);
}

// Round-robin across all active themes so every theme in the wave gets fair representation
const finalWinners = [];
for (let r = 0; r < 3 && finalWinners.length < quota; r++) {
  for (const list of perSeriesWinners) {
    if (finalWinners.length >= quota) break;
    if (list[r]) finalWinners.push(list[r]);
  }
}

const judgedCount = batches.reduce((acc, b) => acc + (b.candidates?.length || 0), 0);

if (finalWinners.length === 0) {
  return [{
    json: {
      noWinners: true,
      rejectedKeys,
      rejectedMd5,
      rejectedDims,
      bucketSizes,
      judgedCount,
    }
  }];
}

return finalWinners.map((w, idx) => ({
  json: {
    ...w,
    noWinners: false,
    bucketSizes,
    rejectedKeys: idx === 0 ? rejectedKeys : [],
    rejectedMd5: idx === 0 ? rejectedMd5 : [],
    rejectedDims: idx === 0 ? rejectedDims : [],
    judgedCount,
  }
}));

const items = $input.all();
const valid = [];

for (const it of items) {
  const bin = it.binary && it.binary.data;
  if (!bin) continue;
  const mime = String(bin.mimeType || '').toLowerCase();
  if (!mime.startsWith('image/')) continue;
  let byteLen = Number(bin.bytes || 0);
  if (!byteLen && typeof bin.data === 'string' && bin.data !== 'filesystem-v2') {
    byteLen = Math.floor(bin.data.length * 0.75);
  }
  if (byteLen > 0 && (byteLen < 80 * 1024 || byteLen > 16 * 1024 * 1024)) continue;

  const cleanName = String(it.json.cleanFilename || bin.fileName || 'wallpaper.jpg');
  valid.push({
    json: {
      series: it.json.series,
      source: it.json.source,
      id: it.json.id,
      key: it.json.key,
      md5: it.json.md5 || '',
      dimKey: it.json.dimKey || '',
      aiScore: it.json.aiScore,
      aiReason: it.json.aiReason || '',
      w: it.json.w,
      h: it.json.h,
      cleanFilename: cleanName,
      bucketSizes: it.json.bucketSizes,
    },
    binary: {
      data: {
        ...bin,
        fileName: cleanName,
      }
    }
  });
}

if (valid.length === 0) {
  return [{ json: { noValidDownloads: true } }];
}

return valid;

