  const limits = { wallhaven: 20, konachan: 30, yandere: 30 };
  for (const se of activeSeries) {
    for (const so of ['wallhaven', 'konachan', 'yandere']) {
      const k = `${se}:${so}`;
      const avail = bucketSizes ? Number(bucketSizes[k] || 0) : 0;
      const cur = Number.isFinite(Number(state.pages[k])) ? Number(state.pages[k]) : 1;
      if (avail < 3) {
        state.pages[k] = cur + 1 > limits[so] ? 1 : cur + 1;
      } else {
        state.pages[k] = cur;
      }
    }
  }
  nextRotWave = (waveIdx + 1) % totalWaves;
}

const trimSet = (setObj, maxLen) => {
  const arr = Array.from(setObj);
  return arr.length > maxLen ? arr.slice(arr.length - maxLen) : arr;
};

