  lines.push(`⏸ 自动搜图待选箱已满（当前 ${inboxBefore} 张 / 上限 ${maxInbox} 张），本次暂停抓取`);
} else {
  lines.push(`• 本次 AI 视觉严选入库：${uploadedCount} 张（从 ${judgedCount} 张高赞候选中筛选 ≥8分）`);
  lines.push(`• 本轮轮换：第 ${waveIdx + 1}/${totalWaves} 组（${seriesDetail}）`);
  lines.push(`• 图源分布：${srcDetail}`);
  lines.push(`• 自动搜图待选箱当前：${inboxNow} 张（上限 ${maxInbox} 张）`);
}
lines.push(`• 正式轮播池：${syncInfo.approvedCount} 张（图床背景：${syncInfo.needSync ? '已自动同步' : '已是最新'}）`);
if (highlights.length) {
  lines.push('');
  lines.push('精选点评：');
  for (const h of highlights) lines.push(`- ${h}`);
}
lines.push('');
lines.push('审核入口：https://YOUR-IMGBED-DOMAIN/dashboard');
lines.push('进入 自动搜图待选 (wallpapers-inbox)：不要的删除（永久不再抓），当壁纸移入 正式壁纸，想生图点右下角紫色魔法棒一键复制。');

return [{
  json: {
    payload: JSON.stringify(newState, null, 2),
    uploadedCount,
    judgedCount,
    uploadedBySeries,
    uploadedBySource,
    inboxNow,
    approvedCount: syncInfo.approvedCount,
    bgSynced: Boolean(syncInfo.needSync),
    shouldNotify: uploadedCount > 0 || Boolean(syncInfo.needSync) || inboxFull,
    message: lines.join('\n'),
  }
}];
